package sqlkit

import (
	"context"
	"database/sql"
	"fmt"
	"regexp"
	"strings"
	"time"

	"github.com/db-fly/db-fly/internal/domain"
)

var (
	numericDefault = regexp.MustCompile(`^-?\d+(\.\d+)?$`)
	keywordDefault = regexp.MustCompile(`(?i)^(NULL|CURRENT_TIMESTAMP(\(\))?|NOW\(\)|CURRENT_DATE|CURRENT_TIME|SYSDATE|SYSTIMESTAMP|GETDATE\(\)|UUID\(\)|TRUE|FALSE)$`)
)

// ColumnConfig 描述字段定义的方言差异。
type ColumnConfig struct {
	Quoter
	Op string
	// AutoIncrementSuffix 在 NULL/NOT NULL 之后追加（如 "GENERATED BY DEFAULT AS IDENTITY"）。
	AutoIncrementSuffix string
	// InlinePrimaryKey 表示把 PRIMARY KEY 作为字段级约束。
	InlinePrimaryKey bool
	// SupportsComment 表示支持字段级 COMMENT 子句。
	SupportsComment bool
	// DefaultExpr 自定义默认值表达式；为空时使用数值/关键字白名单词法。
	DefaultExpr func(value string) string
}

// ColumnDefinition 生成字段定义片段，类型与默认值均经片段安全校验。
func ColumnDefinition(cfg ColumnConfig, c domain.ColumnSpec) (string, error) {
	if cfg.Quoter.Open == "" || cfg.Quoter.Close == "" {
		cfg.Quoter = ANSIQuoter
	}
	name, err := cfg.Quoter.Ident(c.Name)
	if err != nil {
		return "", err
	}
	typ := strings.TrimSpace(c.Type)
	if typ == "" {
		return "", domain.NewError(domain.CodeValidation, cfg.Op, "字段 %s 缺少类型", c.Name)
	}
	if err := ValidateFragment(typ, "字段类型"); err != nil {
		return "", err
	}
	def := name + " " + typ
	if cfg.InlinePrimaryKey && c.PrimaryKey {
		def += " PRIMARY KEY"
	}
	if c.Nullable {
		def += " NULL"
	} else {
		def += " NOT NULL"
	}
	if c.Default != nil {
		value := strings.TrimSpace(*c.Default)
		if err := ValidateFragment(value, "默认值"); err != nil {
			return "", err
		}
		if cfg.DefaultExpr != nil {
			def += " DEFAULT " + cfg.DefaultExpr(value)
		} else if numericDefault.MatchString(value) || keywordDefault.MatchString(value) {
			def += " DEFAULT " + value
		} else {
			def += " DEFAULT '" + EscapeLiteral(value) + "'"
		}
	}
	if cfg.AutoIncrementSuffix != "" && c.AutoIncrement {
		def += " " + cfg.AutoIncrementSuffix
	}
	if cfg.SupportsComment && c.Comment != "" {
		def += " COMMENT '" + EscapeLiteral(c.Comment) + "'"
	}
	return def, nil
}

// ColumnNames 生成逗号分隔的引用字段列表。
func ColumnNames(q Quoter, columns []string) (string, error) {
	if len(columns) == 0 {
		return "", domain.NewError(domain.CodeValidation, "sqlkit.script", "索引至少需要一列")
	}
	out := make([]string, 0, len(columns))
	for _, column := range columns {
		quoted, err := q.Ident(column)
		if err != nil {
			return "", err
		}
		out = append(out, quoted)
	}
	return strings.Join(out, ", "), nil
}

// CreateIndexStmt 生成独立的 CREATE [UNIQUE] INDEX 语句。
func CreateIndexStmt(q Quoter, qualified string, idx domain.IndexSpec) (string, error) {
	name, err := q.Ident(idx.Name)
	if err != nil {
		return "", err
	}
	columns, err := ColumnNames(q, idx.Columns)
	if err != nil {
		return "", err
	}
	kind := "CREATE INDEX"
	if idx.Unique {
		kind = "CREATE UNIQUE INDEX"
	}
	return fmt.Sprintf("%s %s ON %s (%s)", kind, name, qualified, columns), nil
}

// DDLDriver 由各关系型模块实现方言差异；Schema 负责公共的脚本组装、预览与执行。
type DDLDriver interface {
	Name() string
	Qualified(ref domain.ObjectRef) (string, error)
	DatabaseOf(ref domain.ObjectRef) string
	CreateTable(def domain.TableDefinition) ([]string, error)
	AlterTable(ref domain.ObjectRef, changes []domain.SchemaChange) (statements, rollbacks, warnings []string, err error)
	DropObject(ref domain.ObjectRef) ([]string, error)
	ShowCreate(ctx context.Context, ref domain.ObjectRef) (string, error)
	// Truncate / Empty 返回清空数据的方言语句；Empty 为 DELETE FROM 语义。
	Truncate(qualified string) []string
	Empty(qualified string) []string
}

// ScriptRunner 顺序执行 SQL 脚本；PostgreSQL 等按库分池的模块可设置 DBFor。
type ScriptRunner struct {
	DB     *sql.DB
	DBFor  func(ctx context.Context, database string) (*sql.DB, error)
	MapErr func(error) error
	// BatchSplit 可选：把一条语句再拆成批（如 T-SQL 的 GO）。
	BatchSplit func(statement string) []string
}

// Apply 逐条执行脚本；DDL 是否隐式提交由数据库决定，这里不自动回滚已执行语句。
func (r ScriptRunner) Apply(ctx context.Context, script domain.Script) (domain.ApplyResult, error) {
	result := domain.ApplyResult{Outcomes: make([]domain.ExecOutcome, 0, len(script.Statements))}
	db := r.DB
	var err error
	if r.DBFor != nil && script.Database != "" {
		db, err = r.DBFor(ctx, script.Database)
		if err != nil {
			return result, err
		}
	}
	if db == nil {
		return result, domain.NewError(domain.CodeConnection, "sqlkit.apply", "没有可用的数据库连接")
	}
	for _, statement := range script.Statements {
		batches := []string{statement}
		if r.BatchSplit != nil {
			batches = r.BatchSplit(statement)
		}
		for _, batch := range batches {
			execCtx, cancel := context.WithTimeout(ctx, 60*time.Second)
			res, execErr := db.ExecContext(execCtx, batch)
			cancel()
			if execErr != nil {
				if r.MapErr != nil {
					return result, r.MapErr(execErr)
				}
				return result, MapError("sqlkit.apply", execErr)
			}
			affected, _ := res.RowsAffected()
			result.Outcomes = append(result.Outcomes, domain.ExecOutcome{
				Statement: batch, RowsAffected: affected, Message: "执行成功",
			})
		}
	}
	return result, nil
}

// Schema 是 DDLDriver 之上的通用 SchemaEditor 实现。
type Schema struct {
	Driver DDLDriver
	Runner ScriptRunner
	// CreateDatabaseStmt / AlterDatabaseStmt 为空时表示不支持建库/改库。
	CreateDatabaseStmt func(spec domain.DatabaseSpec) (string, error)
	AlterDatabaseStmt  func(name string, spec domain.DatabaseSpec) (string, error)
}

func (s Schema) op() string {
	if s.Driver == nil {
		return "sqlkit.schema"
	}
	return s.Driver.Name() + ".script"
}

func (s Schema) unsupported(what string) error {
	return domain.NewError(domain.CodeUnsupported, s.op(), "%s 不支持%s", s.Driver.Name(), what)
}

func (s Schema) CreateDatabaseScript(_ context.Context, spec domain.DatabaseSpec) (domain.Script, error) {
	if s.CreateDatabaseStmt == nil {
		return domain.Script{}, s.unsupported("创建数据库")
	}
	statement, err := s.CreateDatabaseStmt(spec)
	if err != nil {
		return domain.Script{}, err
	}
	name, err := ANSIQuoter.Ident(spec.Name)
	if err != nil {
		return domain.Script{}, err
	}
	return domain.Script{
		Format: "sql", Statements: []string{statement},
		Rollback: []string{"DROP DATABASE " + name},
		Warnings: []string{"回滚脚本会删除整个数据库及其全部数据，请谨慎使用。"},
	}, nil
}

func (s Schema) AlterDatabaseScript(_ context.Context, name string, spec domain.DatabaseSpec) (domain.Script, error) {
	if s.AlterDatabaseStmt == nil {
		return domain.Script{}, s.unsupported("修改数据库属性")
	}
	statement, err := s.AlterDatabaseStmt(name, spec)
	if err != nil {
		return domain.Script{}, err
	}
	return domain.Script{
		Format: "sql", Statements: []string{statement},
		Warnings: []string{"修改库属性不会自动转换存量数据；无法自动生成回滚脚本。"},
	}, nil
}

func (s Schema) CreateTableScript(_ context.Context, def domain.TableDefinition) (domain.Script, error) {
	statements, err := s.Driver.CreateTable(def)
	if err != nil {
		return domain.Script{}, err
	}
	qualified, err := s.Driver.Qualified(def.Ref)
	if err != nil {
		return domain.Script{}, err
	}
	rollback := "DROP TABLE IF EXISTS " + qualified
	// Oracle 等方言不支持 IF EXISTS，通过可选接口覆盖。
	if provider, ok := s.Driver.(interface{ DropIfExists() bool }); ok && !provider.DropIfExists() {
		rollback = "DROP TABLE " + qualified
	}
	return domain.Script{
		Format: "sql", Statements: statements,
		Database: s.Driver.DatabaseOf(def.Ref),
		Rollback: []string{rollback},
		Warnings: []string{"回滚脚本会删除整张表及全部数据。"},
	}, nil
}

func (s Schema) AlterTableScript(_ context.Context, ref domain.ObjectRef, changes []domain.SchemaChange) (domain.Script, error) {
	statements, rollbacks, warnings, err := s.Driver.AlterTable(ref, changes)
	if err != nil {
		return domain.Script{}, err
	}
	for i, j := 0, len(rollbacks)-1; i < j; i, j = i+1, j-1 {
		rollbacks[i], rollbacks[j] = rollbacks[j], rollbacks[i]
	}
	return domain.Script{
		Format: "sql", Statements: statements,
		Database: s.Driver.DatabaseOf(ref),
		Rollback: rollbacks, Warnings: warnings,
	}, nil
}

func (s Schema) DropObjectScript(_ context.Context, ref domain.ObjectRef) (domain.Script, error) {
	statements, err := s.Driver.DropObject(ref)
	if err != nil {
		return domain.Script{}, err
	}
	return domain.Script{
		Format: "sql", Statements: statements,
		Database: s.Driver.DatabaseOf(ref),
		Warnings: []string{"删除对象不可恢复；若要删除视图请使用对应的 DROP VIEW 语句。"},
	}, nil
}

func (s Schema) ShowCreate(ctx context.Context, ref domain.ObjectRef) (string, error) {
	return s.Driver.ShowCreate(ctx, ref)
}

func (s Schema) Apply(ctx context.Context, script domain.Script) (domain.ApplyResult, error) {
	return s.Runner.Apply(ctx, script)
}

// Maintenance 生成 TRUNCATE / DELETE FROM 的可预览脚本，实现可选端口 domain.TableMaintenance。
type Maintenance struct {
	Driver DDLDriver
	// CapabilityFilter 可选：根据实际能力禁用某个动作。
	Allow func(action domain.TableAction) bool
}

// TableActionScript 返回清空表数据的方言脚本；不提供回滚（数据不可恢复）。
func (m Maintenance) TableActionScript(_ context.Context, ref domain.ObjectRef, action domain.TableAction) (domain.Script, error) {
	if !action.Valid() {
		return domain.Script{}, domain.NewError(domain.CodeValidation, m.Driver.Name()+".maintenance",
			"不支持的清空动作 %q（可用 truncate/empty）", action)
	}
	if m.Allow != nil && !m.Allow(action) {
		return domain.Script{}, domain.NewError(domain.CodeUnsupported, m.Driver.Name()+".maintenance",
			"%s 不支持 %s 操作", m.Driver.Name(), action)
	}
	qualified, err := m.Driver.Qualified(ref)
	if err != nil {
		return domain.Script{}, err
	}
	var statements []string
	var warnings []string
	switch action {
	case domain.TableActionTruncate:
		statements = m.Driver.Truncate(qualified)
		warnings = []string{
			"TRUNCATE 会删除表中全部数据且不写入逐行日志，通常隐式提交、不可回滚。",
			"多数数据库会同时重置自增序列；有外键引用时可能被拒绝。",
		}
	case domain.TableActionEmpty:
		statements = m.Driver.Empty(qualified)
		warnings = []string{
			"DELETE FROM 会逐行删除全部数据，可放入事务但在大表上较慢。",
			"不会重置自增序列，也不会释放表空间；操作不可自动回滚。",
		}
	}
	return domain.Script{
		Format: "sql", Statements: statements, Warnings: warnings,
		Database: m.Driver.DatabaseOf(ref),
	}, nil
}
